/*a!localVariables(*/
    /*21. An employee's age is 65. Write an expression to check if the employee is eligible for retirement (age >=*/
/*65). Return "Eligible" or "Not Eligible".*/
  /*local!age:65,*/
  /*local!condition:if(local!age>=65,"Eligible","Not Eligible"),*/
    /*22. A student scored 75 marks. Write an expression that returns "Pass" if marks >= 50, otherwise "Fail".*/
  /*local!marks:50,*/
  /*local!condition1:if(local!marks>=50,"Pass","Fail"),*/
    /*23. A variable */
/*userInput might be null. Write an expression to check if it is null and return "No input*/
/*provided" if true, otherwise return the value.*/
  /*local!variable:{},*/
  /*local!condition2:if(a!isNullOrEmpty(local!variable),true(),local!variable),*/
    /*24. A product price is $45. Write an expression to check if the price is between $30 and $50 (inclusive) and*/
/*return true or false.*/
  /*local!product:45,*/
  /*local!condition3:if(and(local!product>=30,local!product<=50),true(),false()),*/
   /*25. An order status can be "Pending", "Shipped", or "Delivered". Write an expression using a!match to return*/
/*"In Progress" for "Pending" or "Shipped", and "Completed" for "Delivered". */
  /*local!order:"Delivered",*/
  /*local!condition4:a!match(*/
    /*value: local!order,*/
    /*equals: "Pending",*/
    /*then: "In Progress",*/
    /*equals: "Shipped",*/
    /*then: "Shipped",*/
    /*equals: "Delivered",*/
    /*then:"Completed",*/
    /*default: "Unknown"*/
  /*),*/
   /*A user's role is "Admin". Write an expression to check if the role is either "Admin" or "Manager" and*/
/*return true if yes. */
  /*local!userrole:"Admin",*/
  /*local!condition5:if(or(local!userrole = "Admin", local!userrole="Manager"),true(),false()),*/
   /*27. Two passwords are entered: password1 = "secure123" and password2 = "secure123". Write an expression*/
/*to check if both passwords match exactly. */
  /*local!password:"secure123",*/
  /*local!renter:"secure13",*/
  /*local!ismatch:exact(local!password,local!renter),*/
    /*28. A list of statuses is {true, true, false, true}. Write an expression to check if all values are true.*/
   /*29. A form has three checkboxes with values {false, false, true}. Write an expression to check if at least one*/
/*checkbox is selected.*/
  /*30. A customer's email field is empty (null). Write an expression to return "Email not provided" if null,*/
/*otherwise return "Email provided". */
  /*local!email:"",*/
  /*local!field:if(a!isNullOrEmpty(local!email),"Email not provided","Email provided"),*/
    /*Q31. A temperature reading is 32. Write an expression to return "Freezing" if temperature <= 32, otherwise*/
/*"Above Freezing".*/
  /*local!temperature:32,*/
  /*local!condition6:if(local!temperature<=32,"Freezing","Above Freezing"),*/
    /*32. An invoice amount is $1000. Write an expression to check if it's greater than $500 and return "High Value"*/
/*or "Standard Value".*/
  /*local!invoice:1000,*/
  /*local!condition7:if(local!invoice>500,"High Value","Standard Value"),*/
    /*33. A user's subscription status is "Active". Write an expression to return true if status is "Active", otherwise*/
/*false.*/
  /*local!status:"",*/
  /*local!condition8:if(local!status="Active",true(),false()),*/
    /*Q34. A product rating is 4.5 out of 5. Write an expression to return "Excellent" if rating >= 4, otherwise "Good".*/
  /*local!rating:3,*/
  /*local!condition9:if(local!rating>=4,"Excellent","Good"),*/
    /*35.  Three conditions are checked: condition1 = true, condition2 = false, condition3 = true. Write an expression*/
/*to see if at least one is true.*/
  /*local!cond:false(),*/
  /*local!cond1:true(),*/
  /*local!cond2:true(),*/
  /*local!condition10:if(or(local!cond,local!cond1,local!cond2),true(),false()),*/
    /*36. A shipping option is "Express". Use a!match to return "1-2 days" for "Express", "3-5 days" for "Standard",*/
/*and "5-7 days" for "Economy".*/
  /*local!shipping:"Express",*/
  /*local!condition11:a!match(*/
    /*value: local!shipping,*/
    /*equals: "Express",*/
    /*then:"1-2 days",*/
    /*equals: "Standard",*/
    /*then: "3-5 days",*/
    /*equals: "Economy",*/
    /*then: "5-7 days",*/
    /*default: "Unknown"*/
  /*),*/
    /*37. A variable discount has value null. Write an expression to return 0 if null, otherwise return the discount*/
/*value.*/
  /*local!discount:50,*/
  /*local!condition12:if(a!isNullOrEmpty(local!discount),0,local!discount),*/
    /*38. An account balance is -50. Write an expression to return "Overdrawn" if balance < 0, otherwise*/
/*"Available".*/
  /*local!balance:-50,*/
  /*local!condition13:if(local!balance<0,"Overdrawn","Available"),*/
   /*39. Two boolean values are: isValid = true, isApproved = true. Write an expression to check if both are true. */
  /*local!isValid:true(),*/
  /*local!isapproved:false(),*/
  /*local!condition14:if(and(local!isValid,local!isapproved),true(),false()),*/
    /*40. A grade is "B". Write an expression to check if grade is "A" or "B" and return "Honor Roll", otherwise*/
/*"Standard".*/
  /*local!grade:"c",*/
  /*local!condition15:if(or(local!grade="A",local!grade="B"),"Honor Roll","Standard"),*/
  /*{*/
    /*local!condition,*/
    /*local!condition1,*/
    /*local!condition2,*/
    /*local!condition3,*/
    /*local!condition4,*/
    /*local!condition5,*/
    /*local!ismatch,*/
/*   */
    /*local!condition6,*/
    /*local!condition7,*/
    /*local!condition8,*/
    /*local!condition9,*/
    /*local!condition10,*/
    /*local!condition11,*/
    /*local!condition12,*/
    /*local!condition13,*/
    /*local!condition14,*/
    /*local!condition15*/
  /*}*/
