/*a!localVariables(*/
  /*41. A user entered their name as "john doe". Write an expression to convert it to uppercase: "JOHN DOE".  */
  /*local!name:"john doe",*/
  /*local!text1:upper(local!name),*/
    /*42. A product name is " Laptop " with extra spaces. Write an expression to remove the leading and trailing*/
/*spaces.*/
  /*local!productname:" Laptop ",*/
  /*local!text2:trim(local!productname),*/
   /*Q43. You have two strings: firstName = "Jane" and lastName = "Smith". Write an expression to combine them*/
/*into "Jane Smith". */
  /*local!firstname:"Jane",*/
  /*local!secondname:"Smith",*/
  /*local!text3:concat(local!firstname," ",local!secondname),*/
    /*44. An email address is "USER@EXAMPLE.COM". Write an expression to convert it to lowercase.*/
  /*local!emailaddress:"USER@EXAMPLE.COM",*/
  /*local!text4:lower(local!emailaddress),*/
    /*45. A phone number is stored as "1234567890". Write an expression to extract the first 3 digits (area code).*/
  /*local!phonenumber:"1234567890",*/
  /*local!text5:left(local!phonenumber,3),*/
    /*46. A sentence is "Hello World". Write an expression to get the length (number of characters) of this text.*/
  /*local!sentence:"Hello World",*/
  /*local!text6:len(local!sentence),*/
    /*47. A reference number is "INV-2024-001". Write an expression to extract the last 3 characters: "001".*/
  /*local!referencenumber:"INV-2024-001",*/
  /*local!text7:right(local!referencenumber,3),*/
    /*48. A username is "johnsmith". Write an expression to convert it to proper case: "Johnsmith".*/
  /*local!username:"johnsmith",*/
