   /*49. A text string is "apple,banana,cherry". Write an expression to split it into a list using comma as the*/
/*delimiter. */
  /*local!textstring:"apple,banana,cherry",*/
  /*local!text9:split(local!textstring,","),*/
    /*50. A product code is "PROD-12345". Write an expression to replace "PROD" with "ITEM" to get "ITEM*/
/*12345".*/
  /*local!productcode:"PROD-12345",*/
  /*local!text10:substitute(local!productcode,"PROD","ITEM"),*/
   /*51. A customer's full name is "MARY JOHNSON". Write an expression to convert it to proper case: "Mary*/
/*Johnson". */
  /*local!customer:"MARY JOHNSON",*/
  /*local!text11:proper(local!customer),*/
   /*52. A description is "Product Description Here". Write an expression to extract the first 10 characters. */
  /*local!description:"Product Description Here",*/
  /*local!text12:left(local!description,10),*/
    /*53. A URL is "*/
/*www.example.com". Write an expression to add "https://" at the beginning to make*/
/*"https://www.example.com".*/
  /*local!url:"www.example.com",*/
  /*local!text13:concat("https://",local!url),*/
   /*54. A serial number is "SN123456789". Write an expression to extract characters from position 3 to 8 (the*/
/*numbers "123456"). */
  /*local!serialnumber:"SN123456789",*/
  /*local!text14:extract(local!serialnumber,3,8),*/
    /*55. A text is "Hello". Write an expression to repeat this text 3 times: "HelloHelloHello".*/
  /*local!repeat:"Hello",*/
  /*local!text15:rept(local!repeat,3),*/
    /*56. A sentence is "The quick brown fox". Write an expression to find the position of the word "brown" in the*/
/*sentence.*/
  /*local!position:"The quick brown fox",*/
  /*local!text16:find("brown",local!position),*/
    /*57. An address is "123 Main St". Write an expression to extract the last 2 characters: "St".*/
  /*local!address:"123 Main St",*/
  /*local!text17:right(local!address,2),*/
    /*58. A ticket number is "TKT-2024-500". Write an expression to replace "2024" with "2025".*/
  /*local!ticketnumber:"TKT-2024-500",*/
  /*local!text18:substitute(local!ticketnumber,"2024","2025"),*/
    /*59. A list of words is {"apple", "banana", "cherry"}. Write an expression to join them with "-" to create*/
/*"apple-banana-cherry".*/
  /*local!words:{"apple", "banana", "cherry"},*/
  /*local!text19:joinarray(local!words,"-"),*/
   /*Q60. A string is "Hello-World-Test". Write an expression to split it by "-" into a list: {"Hello", "World", "Test"}. */
  /*local!string: "Hello-World-Test",*/
  /*local!test20: split(local!string, "-"),*/
