/*a!localVariables(*/
   /*Q81. A student scored marks in three subjects: 85, 90, 78. Write an expression to calculate the total marks. */
  /*local!subject1:85,*/
  /*local!subject2:90,*/
  /*local!subject3:78,*/
  /*local!math1:sum(local!subject1,local!subject2,local!subject3),*/
   /*Q82. A product costs $125.50. Write an expression to round this to the nearest whole number. */
  /*local!product:125.50,*/
  /*local!math2:ceiling(local!product),*/
   /*Four employees worked 8, 7, 9, and 6 hours respectively. Write an expression to calculate the average*/
/*hours worked.  */
  /*local!employees:8,*/
  /*local!employees1:7,*/
  /*local!employees2:9,*/
  /*local!employees3:6,*/
  /*local!math3:average(local!employees,local!employees1,local!employees2,local!employees3),*/
   /*84. A list of sales figures is {1200, 850, 1500, 900, 1100}. Write an expression to find the maximum value. */
  /*local!sales:{1200, 850, 1500, 900, 1100},*/
  /*local!math4:max(local!sales),*/
   /*85. A discount calculation results in $45.75. Write an expression to round this up to $46 */
  /*local!discount:45.75,*/
