    /*An order total is $78.25. Write an expression to round this down to $78.*/
  /*local!dis:78.25,*/
  /*local!math6:rounddown(local!dis,0),*/
   /*87. A number is -15. Write an expression to get its absolute (positive) value */
  /*local!number:-15,*/
